# Test fixtures and test suite for semantic version bumper
# Tests use red/green TDD: write failing test first, implement to pass, refactor

$testDataDir = Join-Path $PSScriptRoot "test-fixtures"

# Remove and recreate test fixtures directory
if (Test-Path $testDataDir) {
    Remove-Item $testDataDir -Recurse -Force
}
New-Item -ItemType Directory -Path $testDataDir | Out-Null

# Create mock git commit logs for testing
function Create-MockCommitLog {
    param(
        [string]$Path,
        [array]$Commits
    )
    $commitLog = $Commits -join "`n"
    Set-Content -Path $Path -Value $commitLog -Encoding UTF8
}

# Test 1: Parse semantic version from package.json
Describe "Parse-SemanticVersion" {
    It "should parse version from package.json" {
        $packageJson = @{
            version = "1.0.0"
            name = "test-app"
        } | ConvertTo-Json

        $fixture = Join-Path $testDataDir "package-1.0.0.json"
        Set-Content -Path $fixture -Value $packageJson

        # This will fail until we implement the function
        { Parse-SemanticVersion -FilePath $fixture } | Should -Not -Throw
        (Parse-SemanticVersion -FilePath $fixture) | Should -Be "1.0.0"
    }

    It "should handle version.txt files" {
        $fixture = Join-Path $testDataDir "version-2.3.4.txt"
        Set-Content -Path $fixture -Value "2.3.4"

        (Parse-SemanticVersion -FilePath $fixture) | Should -Be "2.3.4"
    }

    It "should throw on missing file" {
        { Parse-SemanticVersion -FilePath "/nonexistent/version.json" } | Should -Throw
    }
}

# Test 2: Parse conventional commits to determine version bump type
Describe "Get-VersionBumpType" {
    It "should detect PATCH for fix commit" {
        $commitLog = @(
            "fix: resolve null reference error",
            "feat: add new feature"
        )
        $fixture = Join-Path $testDataDir "commits-patch.txt"
        Create-MockCommitLog -Path $fixture -Commits $commitLog

        (Get-VersionBumpType -CommitLogPath $fixture) | Should -Be "patch"
    }

    It "should detect MINOR for feat commit" {
        $commitLog = @(
            "feat: add new user dashboard"
        )
        $fixture = Join-Path $testDataDir "commits-minor.txt"
        Create-MockCommitLog -Path $fixture -Commits $commitLog

        (Get-VersionBumpType -CommitLogPath $fixture) | Should -Be "minor"
    }

    It "should detect MAJOR for breaking change" {
        $commitLog = @(
            "feat: redesign API",
            "BREAKING CHANGE: removed v1 endpoints"
        )
        $fixture = Join-Path $testDataDir "commits-major.txt"
        Create-MockCommitLog -Path $fixture -Commits $commitLog

        (Get-VersionBumpType -CommitLogPath $fixture) | Should -Be "major"
    }

    It "should prefer highest bump level (major > minor > patch)" {
        $commitLog = @(
            "fix: bug fix",
            "feat: new feature",
            "BREAKING CHANGE: removed API"
        )
        $fixture = Join-Path $testDataDir "commits-mixed.txt"
        Create-MockCommitLog -Path $fixture -Commits $commitLog

        (Get-VersionBumpType -CommitLogPath $fixture) | Should -Be "major"
    }

    It "should return none for non-conventional commits" {
        $commitLog = @(
            "random commit message",
            "update readme"
        )
        $fixture = Join-Path $testDataDir "commits-none.txt"
        Create-MockCommitLog -Path $fixture -Commits $commitLog

        (Get-VersionBumpType -CommitLogPath $fixture) | Should -Be "none"
    }
}

# Test 3: Calculate next semantic version
Describe "Get-NextSemanticVersion" {
    It "should bump patch version" {
        (Get-NextSemanticVersion -CurrentVersion "1.2.3" -BumpType "patch") | Should -Be "1.2.4"
    }

    It "should bump minor version and reset patch" {
        (Get-NextSemanticVersion -CurrentVersion "1.2.3" -BumpType "minor") | Should -Be "1.3.0"
    }

    It "should bump major version and reset minor/patch" {
        (Get-NextSemanticVersion -CurrentVersion "1.2.3" -BumpType "major") | Should -Be "2.0.0"
    }

    It "should handle version 0.x.x correctly" {
        (Get-NextSemanticVersion -CurrentVersion "0.1.2" -BumpType "minor") | Should -Be "0.2.0"
        (Get-NextSemanticVersion -CurrentVersion "0.1.2" -BumpType "major") | Should -Be "1.0.0"
    }

    It "should not change version for none bump type" {
        (Get-NextSemanticVersion -CurrentVersion "1.2.3" -BumpType "none") | Should -Be "1.2.3"
    }
}

# Test 4: Update version in files
Describe "Update-VersionInFile" {
    It "should update version in package.json" {
        $packageJson = @{
            version = "1.0.0"
            name = "test-app"
        } | ConvertTo-Json

        $fixture = Join-Path $testDataDir "package-update.json"
        Set-Content -Path $fixture -Value $packageJson

        Update-VersionInFile -FilePath $fixture -NewVersion "1.1.0"

        $updated = Get-Content -Path $fixture | ConvertFrom-Json
        $updated.version | Should -Be "1.1.0"
    }

    It "should update version in version.txt" {
        $fixture = Join-Path $testDataDir "version-update.txt"
        Set-Content -Path $fixture -Value "1.0.0"

        Update-VersionInFile -FilePath $fixture -NewVersion "1.1.0"

        $updated = Get-Content -Path $fixture
        $updated | Should -Be "1.1.0"
    }

    It "should backup original file before updating" {
        $fixture = Join-Path $testDataDir "version-backup.txt"
        Set-Content -Path $fixture -Value "1.0.0"

        Update-VersionInFile -FilePath $fixture -NewVersion "1.1.0"

        $backup = "$fixture.bak"
        Test-Path $backup | Should -Be $true
        (Get-Content -Path $backup) | Should -Be "1.0.0"
    }
}

# Test 5: Generate changelog entries
Describe "Generate-ChangelogEntry" {
    It "should generate changelog for new version" {
        $commitLog = @(
            "feat: add dashboard widget",
            "fix: resolve memory leak",
            "docs: update readme"
        )
        $fixture = Join-Path $testDataDir "commits-changelog.txt"
        Create-MockCommitLog -Path $fixture -Commits $commitLog

        $changelog = Generate-ChangelogEntry -CommitLogPath $fixture -NewVersion "1.1.0" -Date (Get-Date)

        $changelog | Should -Match "1.1.0"
        $changelog | Should -Match "dashboard widget"
        $changelog | Should -Match "memory leak"
    }

    It "should categorize commits by type" {
        $commitLog = @(
            "feat: new feature 1",
            "feat: new feature 2",
            "fix: bug fix 1"
        )
        $fixture = Join-Path $testDataDir "commits-category.txt"
        Create-MockCommitLog -Path $fixture -Commits $commitLog

        $changelog = Generate-ChangelogEntry -CommitLogPath $fixture -NewVersion "1.1.0" -Date (Get-Date)

        $changelog | Should -Match "feat|feature|feature"
        $changelog | Should -Match "fix|bug|fix"
    }
}

# Test 6: Main orchestration - parse, determine bump, update, generate changelog
Describe "Invoke-SemanticVersionBump" {
    It "should complete full version bump workflow" {
        $packageJson = @{
            version = "1.0.0"
            name = "test-app"
        } | ConvertTo-Json

        $versionFile = Join-Path $testDataDir "workflow-package.json"
        Set-Content -Path $versionFile -Value $packageJson

        $commitLog = @(
            "feat: add new dashboard"
        )
        $commitFile = Join-Path $testDataDir "workflow-commits.txt"
        Create-MockCommitLog -Path $commitFile -Commits $commitLog

        $result = Invoke-SemanticVersionBump -VersionFilePath $versionFile -CommitLogPath $commitFile

        $result.OldVersion | Should -Be "1.0.0"
        $result.NewVersion | Should -Be "1.1.0"
        $result.BumpType | Should -Be "minor"

        $updated = Get-Content -Path $versionFile | ConvertFrom-Json
        $updated.version | Should -Be "1.1.0"
    }
}

