        elseif ($lowerCommit -match "^fix:") {
            if ($bumpLevels["patch"] -gt $maxLevel) {
                $maxLevel = $bumpLevels["patch"]
                $resultBump = "patch"
            }
        }
    }

    return $resultBump
}

# Calculate next semantic version based on bump type
function Get-NextSemanticVersion {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$CurrentVersion,

        [Parameter(Mandatory = $true)]
        [ValidateSet("major", "minor", "patch", "none")]
        [string]$BumpType
    )

    if ($BumpType -eq "none") {
        return $CurrentVersion
    }

    # Parse current version
    $parts = $CurrentVersion -split "\."
    if ($parts.Count -ne 3) {
        throw "Invalid semantic version format: $CurrentVersion. Expected major.minor.patch"
    }

    [int]$major = $parts[0]
    [int]$minor = $parts[1]
    [int]$patch = $parts[2]

    # Calculate next version
    switch ($BumpType) {
        "major" {
            $major++
            $minor = 0
            $patch = 0
        }
        "minor" {
            $minor++
            $patch = 0
        }
        "patch" {
            $patch++
        }
    }

    return "$major.$minor.$patch"
}

# Update version in a package.json or version.txt file
function Update-VersionInFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$FilePath,

        [Parameter(Mandatory = $true)]
        [string]$NewVersion
    )

    if (-not (Test-Path -LiteralPath $FilePath)) {
        throw "Version file not found: $FilePath"
    }

    # Create backup
    $backupPath = "$FilePath.bak"
    Copy-Item -LiteralPath $FilePath -Destination $backupPath -Force

    try {
        $extension = [System.IO.Path]::GetExtension($FilePath).ToLower()

        if ($extension -eq ".json") {
            $json = Get-Content -LiteralPath $FilePath | ConvertFrom-Json
            $json.version = $NewVersion
            $json | ConvertTo-Json | Set-Content -LiteralPath $FilePath -Encoding UTF8
        }
        elseif ($extension -eq ".txt") {
            Set-Content -LiteralPath $FilePath -Value $NewVersion -Encoding UTF8 -NoNewline
        }
        else {
            throw "Unsupported file format: $extension"
        }
    }
    catch {
        Remove-Item -LiteralPath $backupPath -Force
        throw $_
    }
}

# Generate changelog entry from conventional commits
function Generate-ChangelogEntry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$CommitLogPath,

        [Parameter(Mandatory = $true)]
        [string]$NewVersion,

        [Parameter(Mandatory = $true)]
        [datetime]$Date
    )

    if (-not (Test-Path -LiteralPath $CommitLogPath)) {
        throw "Commit log file not found: $CommitLogPath"
    }

    $commits = Get-Content -LiteralPath $CommitLogPath -Encoding UTF8 | Where-Object { $_.Trim() -ne "" }

    $changelog = @()
    $changelog += "## [$NewVersion] - $($Date.ToString('yyyy-MM-dd'))"
    $changelog += ""

    $features = @()
    $fixes = @()
    $breaking = @()

    foreach ($commit in $commits) {
        $lowerCommit = $commit.ToLower()

        if ($lowerCommit -match "^breaking change") {
            $breaking += $commit
        }
        elseif ($lowerCommit -match "breaking change:") {
            $breaking += $commit
        }
        elseif ($lowerCommit -match "^feat:") {
            $msg = $commit -replace "^feat:\s*", ""
            $features += "- $msg"
        }
        elseif ($lowerCommit -match "^fix:") {
            $msg = $commit -replace "^fix:\s*", ""
            $fixes += "- $msg"
        }
    }

    if ($breaking.Count -gt 0) {
        $changelog += "### ⚠️ Breaking Changes"
        foreach ($change in $breaking) {
            $changelog += "- $change"
        }
        $changelog += ""
    }

    if ($features.Count -gt 0) {
        $changelog += "### Features"
        $changelog += $features
        $changelog += ""
    }

    if ($fixes.Count -gt 0) {
        $changelog += "### Fixes"
        $changelog += $fixes
        $changelog += ""
    }

    return $changelog -join "`n"
}

# Main orchestration function
function Invoke-SemanticVersionBump {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$VersionFilePath,

        [Parameter(Mandatory = $true)]
        [string]$CommitLogPath
    )

    # Step 1: Parse current version
    $oldVersion = Parse-SemanticVersion -FilePath $VersionFilePath
    Write-Verbose "Current version: $oldVersion"

    # Step 2: Determine bump type from commits
    $bumpType = Get-VersionBumpType -CommitLogPath $CommitLogPath
    Write-Verbose "Bump type: $bumpType"

    # Step 3: Calculate new version
    $newVersion = Get-NextSemanticVersion -CurrentVersion $oldVersion -BumpType $bumpType
    Write-Verbose "New version: $newVersion"

    # Step 4: Update version file
    Update-VersionInFile -FilePath $VersionFilePath -NewVersion $newVersion

    # Step 5: Generate changelog
    $changelog = Generate-ChangelogEntry -CommitLogPath $CommitLogPath -NewVersion $newVersion -Date (Get-Date)

    # Return results
    return @{
        OldVersion  = $oldVersion
        NewVersion  = $newVersion
        BumpType    = $bumpType
        Changelog   = $changelog
        VersionFile = $VersionFilePath
    }
}

